-- PostgreSQL intervals
SELECT now() - INTERVAL '1 day';
SELECT now() - INTERVAL '3 months';

-- Date truncation (granularity)
SELECT date_trunc('hour', ts) AS hour_bucket,
       COUNT(*)
FROM events
GROUP BY hour_bucket;

-- Generate series (regular intervals)
SELECT generate_series('2024-01-01'::date,
                        '2024-01-31'::date,
                        INTERVAL '1 day') AS day;

