-- Point: single coordinate pair
SELECT ST_MakePoint(-122.4194, 37.7749) AS sf;
-- LINESTRING: ordered sequence of points
SELECT ST_MakeLine(ARRAY[ST_MakePoint(0,0), ST_MakePoint(1,1)]);
-- POLYGON: closed ring (first=last)
SELECT ST_MakePolygon(ST_GeomFromText('LINESTRING(0 0, 1 0, 1 1, 0 1, 0 0)'));
-- MULTI* variants for collections

-- Set SRID on geometry
SELECT ST_SetSRID(ST_MakePoint(-122.4, 37.7), 4326);

-- Transform to Web Mercator (meters)
SELECT ST_Transform(geom, 3857);

-- Distance in meters (requires projected CRS)
SELECT ST_Distance(
  ST_Transform(a.geom, 3857),
  ST_Transform(b.geom, 3857)
) FROM a, b;
